// Кейс: .qa/tests/monitoring/MON-010.md · план: .qa/e2e-app/specs/app.md (1.1)
// Чекбоксы сообщают VoiceOver состояние «отмечено / не отмечено» и оно меняется по нажатию.
// Мониторинг НЕ запускается («התחלת ניטור» на шаге 3 не нажимается) — данных не создаёт.
import { by, assert, checkedFromValue } from '../../lib/appium.mjs';
import { passSafetyCheck } from '../../lib/banci.mjs';

export const name = 'Чекбоксы: значение доступности unchecked → checked (шаг 2 «כל שטח המים…», шаг 3 «מי בבריכה היום?») #e41636dd @iphone @app';

async function state(el) {
  return checkedFromValue(await el.attr('value'));
}

/** Нажать и дождаться смены состояния (без фиксированной паузы). */
async function toggleAndExpect(el, expected, what) {
  await el.click();
  const end = Date.now() + 5000;
  let s;
  while (Date.now() < end) {
    s = await state(el);
    if (s === expected) return;
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error(`Проверка не прошла: «${what}» после нажатия — ${expected ? 'checked' : 'unchecked'}, сейчас value=«${await el.attr('value')}»`);
}

export default async function (app) {
  // 1. Шаг 1 «בדיקת בטיחות» → «המשך».
  await passSafetyCheck(app);

  // 2. Шаг 2 «כיוון מצלמה»: чекбокс «כל שטח המים נראה…».
  const water = await app.waitFor(by.begins('כל שטח המים נראה'), { timeout: 20000, what: 'чекбокс «כל שטח המים נראה…» на шаге 2' });
  const v0 = await water.attr('value');
  const s0 = checkedFromValue(v0);
  assert(s0 !== null, `у чекбокса «כל שטח המים נראה…» есть состояние в значении доступности (value=«${v0}»)`);
  if (s0) await toggleAndExpect(water, false, 'כל שטח המים נראה…');
  await toggleAndExpect(water, true, 'כל שטח המים נראה…'); // unchecked → checked
  await toggleAndExpect(water, false, 'כל שטח המים נראה…'); // checked → unchecked
  await toggleAndExpect(water, true, 'כל שטח המים נראה…'); // оставить отмеченным, чтобы пройти дальше

  // 3. «המשך» → шаг 3 «מי בבריכה היום?».
  await app.tap(by.exact('המשך', 'Button'), { what: '«המשך» на шаге камеры' });
  await app.waitFor(by.contains('מי בבריכה היום'), { timeout: 15000, what: 'шаг 3 «מי בבריכה היום?»' });

  // 4. Дети: элементы со значением доступности чекбокса (кроме «בחירת כולם»).
  const boxes = await app.findAll('value BEGINSWITH[c] "checkbox" OR value CONTAINS "מסומן"');
  const kids = [];
  for (const b of boxes) {
    const n = String(await b.attr('name') ?? '');
    if (!/בחירת כולם|כל שטח המים/.test(n)) kids.push({ el: b, name: n });
  }
  assert(kids.length > 0, 'ПРЕДУСЛОВИЕ: на шаге 3 есть хотя бы один ребёнок с чекбоксом (у аккаунта есть дети)');
  const kid = kids[0];
  const k0 = await state(kid.el);
  assert(k0 !== null, `у ребёнка «${kid.name}» есть состояние в значении доступности`);
  await toggleAndExpect(kid.el, !k0, kid.name);
  await toggleAndExpect(kid.el, k0, kid.name); // вернуть как было

  // 5. Выход без запуска мониторинга.
  await app.restart();
}
